// Same coordinate transform for the curve, level lines and arrows.
export function profileFigure({reactants=40,products=25,peak=90,arrows=true,labels=false,origin='reactants'}={}){if(![reactants,products,peak].every(Number.isFinite)||peak<=Math.max(reactants,products))throw new Error('Peak must exceed endpoint energies');const y=v=>250-v*2,R=y(reactants),P=y(products),T=y(peak);const text=(x,y,s,size=18)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="currentColor" font-size="${size}" font-family="sans-serif">${s}</text>`;const arrow=(x,a,b,name)=>`<path d="M${x} ${a}V${b} M${x-4} ${b+(b<a?5:-5)}L${x} ${b}L${x+4} ${b+(b<a?5:-5)} M${x-4} ${a+(b<a?-5:5)}L${x} ${a}L${x+4} ${a+(b<a?-5:5)}" stroke="currentColor" fill="none" stroke-width="1.4"/>${text(x+15,(a+b)/2+4,name,16)}`;
return `<svg class="profile-figure" viewBox="0 0 460 310" role="img" aria-label="Reaction profile: products ${products<reactants?'lower':'higher'} in energy than reactants; peak above both. ${arrows?'Arrow A runs from '+(origin==='products'?'product':origin==='baseline'?'baseline':'reactant')+' level to peak; arrow B joins the reactant and product energy levels.':''}"><path d="M45 25V265H430" stroke="currentColor" fill="none" stroke-width="1.5"/>${text(234,298,'Reaction progress')}${text(45,15,'Energy')}<path d="M65 ${R}H120 C165 ${R} 180 ${T} 230 ${T} S305 ${P} 345 ${P} H390" stroke="#ed8b78" fill="none" stroke-width="3"/><path d="M65 ${R}H410 M230 ${T}H165 M345 ${P}H410" stroke="currentColor" stroke-opacity=".3" stroke-dasharray="4 4" fill="none"/>${text(91,R-12,'Reactants',16)}${text(358,P+20,'Products',16)}${arrows?arrow(165,origin==='products'?P:origin==='baseline'?250:R,T,labels?'Activation':'A')+arrow(410,R,P,labels?'Overall':'B'):''}</svg>`;}
